<?php
require_once __DIR__.'/phase5_lib.php';
require_login();p5_admin();p5_require_ready();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=p5_get_string('action',30);
    if($action==='supplier'){
        $name=p5_get_string('supplier_name',150);$person=p5_get_string('contact_name',120);$phone=p5_get_string('phone',40);$address=p5_get_string('address',400);
        if($name==='')p5_bad_request('Supplier Name লিখুন।');
        $pdo->beginTransaction();try{
            $st=$pdo->prepare('INSERT INTO suppliers(supplier_name,contact_name,phone,address,created_by) VALUES(?,?,?,?,?)');$st->execute([$name,$person?:null,$phone?:null,$address?:null,(int)user()['id']]);
            p5_audit('supplier.created','suppliers',(int)$pdo->lastInsertId(),null,'Supplier registered: '.$name);
            $pdo->commit();flash('Supplier তৈরি হয়েছে।');redirect('suppliers.php#supplier-directory');
        }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();throw $ex;}
    }
    if($action==='purchase'){
        $pid=(int)($_POST['project_id']??0);$sid=(int)($_POST['supplier_id']??0);$itemId=(int)($_POST['item_id']??0);
        $date=p5_get_string('purchase_date',10);$qty=p5_qty($_POST['quantity']??'');$price=p5_money($_POST['unit_price']??'');$invoice=p5_get_string('invoice_no',100);$note=p5_get_string('notes',500);
        if(!$pid||!$sid||!$itemId||!valid_date($date)||$qty===null||$price===null)p5_bad_request('প্রকল্প, Supplier, Material, Quantity, Price ও Date দিন।');
        p5_project($pid,'view_project');
        if($invoice==='')p5_bad_request('Purchase-এর Invoice নম্বর লিখুন।');
        $total=p5_money(number_format((float)$qty*(float)$price,2,'.',''));
        if($total===null)p5_bad_request('Purchase-এর মোট Amount সীমার বাইরে।');
        try{
            $pdo->beginTransaction();
            $st=$pdo->prepare('SELECT id FROM suppliers WHERE id=?');$st->execute([$sid]);if(!$st->fetchColumn())throw new InvalidArgumentException('Supplier পাওয়া যায়নি।');
            $st=$pdo->prepare('SELECT id FROM inventory_items WHERE id=? AND project_id=?');$st->execute([$itemId,$pid]);if(!$st->fetchColumn())throw new InvalidArgumentException('Material নির্বাচিত প্রকল্পের নয়।');
            $st=$pdo->prepare('INSERT INTO supplier_purchases(project_id,supplier_id,item_id,invoice_no,purchase_date,quantity,unit_price,total_amount,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');
            $st->execute([$pid,$sid,$itemId,$invoice?:null,$date,$qty,$price,$total,$note?:null,(int)user()['id']]);$purchaseId=(int)$pdo->lastInsertId();
            p5_stock_move($pdo,$itemId,$pid,'in',$qty,$date,$purchaseId,'Supplier purchase #'.$purchaseId);
            p5_audit('purchase.created','supplier_purchases',$purchaseId,$pid,'Purchase recorded: BDT '.$total.'; item #'.$itemId);
            $pdo->commit();flash('ক্রয় সংরক্ষিত হয়েছে এবং Stock স্বয়ংক্রিয়ভাবে বেড়েছে।');redirect('suppliers.php#purchase-directory');
        }catch(InvalidArgumentException $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');redirect('suppliers.php#new-purchase');}
         catch(PDOException $ex){if($pdo->inTransaction())$pdo->rollBack();if($ex->getCode()==='23000'){flash('Supplier-এর Invoice নম্বরটি আগে ব্যবহার হয়েছে।','error');redirect('suppliers.php#new-purchase');}throw $ex;}
         catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();throw $ex;}
    }
    if($action==='payment'){
        $token=$_POST['payment_nonce']??'';
        if(!is_string($token)||!hash_equals((string)($_SESSION['p5_payment_nonce']??''),$token)||$token===''){http_response_code(409);exit('Payment form expired or already submitted. Refresh the page.');}
        unset($_SESSION['p5_payment_nonce']);
        $purchaseId=(int)($_POST['purchase_id']??0);$amount=p5_money($_POST['amount']??'');$date=p5_get_string('payment_date',10);$method=p5_get_string('method',15);$ref=p5_get_string('reference_no',120);$note=p5_get_string('note',500);
        if(!$purchaseId||$amount===null||!valid_date($date)||!in_array($method,['cash','bank','cheque','mobile'],true))p5_bad_request('Purchase, Amount, Date ও Payment Method সঠিক দিন।');
        try{$pdo->beginTransaction();
            // The purchase row lock serializes payments: two concurrent requests cannot overpay.
            $st=$pdo->prepare('SELECT id,project_id,total_amount FROM supplier_purchases WHERE id=? FOR UPDATE');$st->execute([$purchaseId]);$purchase=$st->fetch();
            if(!$purchase)throw new InvalidArgumentException('Purchase পাওয়া যায়নি।');
            $st=$pdo->prepare('SELECT COALESCE(SUM(amount),0) paid FROM supplier_payments WHERE purchase_id=?');$st->execute([$purchaseId]);$paid=(float)$st->fetchColumn();
            $remaining=round((float)$purchase['total_amount']-$paid,2);
            if(round((float)$amount-$remaining,2)>0||$remaining<=0)throw new InvalidArgumentException('বকেয়ার বেশি Payment করা যাবে না।');
            $st=$pdo->prepare('INSERT INTO supplier_payments(purchase_id,payment_date,amount,method,reference_no,note,created_by) VALUES(?,?,?,?,?,?,?)');
            $st->execute([$purchaseId,$date,$amount,$method,$ref?:null,$note?:null,(int)user()['id']]);$paymentId=(int)$pdo->lastInsertId();
            p5_audit('payment.created','supplier_payments',$paymentId,(int)$purchase['project_id'],'Supplier payment BDT '.$amount.' for purchase #'.$purchaseId);
            $pdo->commit();flash('Supplier Payment সফলভাবে সংরক্ষিত হয়েছে।');redirect('suppliers.php#purchase-directory');
        }catch(InvalidArgumentException $ex){if($pdo->inTransaction())$pdo->rollBack();flash($ex->getMessage(),'error');redirect('suppliers.php#new-payment');}
         catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();throw $ex;}
    }
    p5_bad_request('Unknown action.');
}
$_SESSION['p5_payment_nonce']=bin2hex(random_bytes(16));
$projects=allowed_projects('view_project');
$allSuppliers=$pdo->query('SELECT s.*,COALESCE(a.total,0) total,COALESCE(a.paid,0) paid FROM suppliers s LEFT JOIN (SELECT p.supplier_id,SUM(p.total_amount) total,SUM(COALESCE(pay.paid,0)) paid FROM supplier_purchases p LEFT JOIN (SELECT purchase_id,SUM(amount) paid FROM supplier_payments GROUP BY purchase_id) pay ON pay.purchase_id=p.id GROUP BY p.supplier_id) a ON a.supplier_id=s.id ORDER BY s.id DESC')->fetchAll();
$items=$pdo->query('SELECT i.id,i.project_id,i.item_name,i.unit,p.title project_title FROM inventory_items i JOIN projects p ON p.id=i.project_id ORDER BY p.title,i.item_name')->fetchAll();
$purchases=$pdo->query('SELECT p.*,s.supplier_name,i.item_name,i.unit,pr.title project_title,COALESCE(pay.paid,0) paid FROM supplier_purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN inventory_items i ON i.id=p.item_id JOIN projects pr ON pr.id=p.project_id LEFT JOIN (SELECT purchase_id,SUM(amount) paid FROM supplier_payments GROUP BY purchase_id) pay ON pay.purchase_id=p.id ORDER BY p.id DESC LIMIT 300')->fetchAll();
$outstandingPurchases=$pdo->query('SELECT p.id,p.total_amount,s.supplier_name,COALESCE(pay.paid,0) paid FROM supplier_purchases p JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN (SELECT purchase_id,SUM(amount) paid FROM supplier_payments GROUP BY purchase_id) pay ON pay.purchase_id=p.id WHERE p.total_amount>COALESCE(pay.paid,0) ORDER BY p.id DESC LIMIT 2000')->fetchAll();
$payments=$pdo->query('SELECT pay.*,s.supplier_name,p.invoice_no,p.project_id FROM supplier_payments pay JOIN supplier_purchases p ON p.id=pay.purchase_id JOIN suppliers s ON s.id=p.supplier_id ORDER BY pay.id DESC LIMIT 30')->fetchAll();
$sumInvoiced=$sumPaid=$dueCount=0.0;foreach($allSuppliers as $s){$sumInvoiced+=(float)$s['total'];$sumPaid+=(float)$s['paid'];}
foreach($purchases as $p){if((float)$p['total_amount']-(float)$p['paid']>0.005)$dueCount++;}
include 'layout_top.php';
?>
<div class="p5-page" data-p5-page="suppliers"><section class="p5-hero"><div class="p5-hero-inner"><span class="p5-eyebrow">PROCUREMENT / 03</span><h1>সরবরাহকারী থেকে <em>সঠিক হিসাব।</em></h1><p>এক জায়গায় Supplier, Material Purchase, Supplier Payment এবং বকেয়া ট্র্যাক করুন। প্রতিটি Purchase-এ Stock নিজে থেকে বাড়বে।</p></div><span class="p5-hero-art" aria-hidden="true">≡</span></section>
<section class="p5-kpis"><article class="p5-kpi"><span class="p5-kpi-label">Supplier</span><strong><?= count($allSuppliers) ?></strong><small>নিবন্ধিত সরবরাহকারী</small></article><article class="p5-kpi"><span class="p5-kpi-label">মোট Purchase</span><strong><?= p5_cash_view($sumInvoiced) ?></strong><small>Invoice-এর মোট মূল্য</small></article><article class="p5-kpi"><span class="p5-kpi-label">মোট Payment</span><strong><?= p5_cash_view($sumPaid) ?></strong><small>পরিশোধিত টাকা</small></article><article class="p5-kpi"><span class="p5-kpi-label">মোট বকেয়া</span><strong><?= p5_cash_view($sumInvoiced-$sumPaid) ?></strong><small>অপরিশোধিত Invoice</small></article></section>
<div class="p5-duo"><section class="p5-surface" id="new-supplier"><div class="p5-section-heading"><div><span class="p5-overline">SUPPLIER PROFILE</span><h2>নতুন Supplier</h2><p>বিশ্বস্ত সরবরাহকারীর যোগাযোগ তথ্য রাখুন।</p></div></div><form method="post" class="p5-form p5-form-two"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="supplier"><div class="p5-field p5-span2"><label for="supplierName">প্রতিষ্ঠানের নাম <b>*</b></label><input id="supplierName" name="supplier_name" maxlength="150" required placeholder="যেমন: Rahman Trading Corporation"></div><div class="p5-field"><label for="supplierContact">যোগাযোগের ব্যক্তি</label><input id="supplierContact" name="contact_name" maxlength="120" placeholder="যেমন: মো. করিম"></div><div class="p5-field"><label for="supplierPhone">মোবাইল</label><input id="supplierPhone" name="phone" maxlength="40" placeholder="যেমন: 01700 000000"></div><div class="p5-field p5-span2"><label for="supplierAddress">ঠিকানা</label><input id="supplierAddress" name="address" maxlength="400" placeholder="যেমন: আম্বরখানা, সিলেট"></div><div class="p5-form-foot"><button type="submit" class="p5-btn p5-btn-primary">Supplier Save ↗</button></div></form></section>
<section class="p5-surface" id="new-purchase"><div class="p5-section-heading"><div><span class="p5-overline">PURCHASE INVOICE</span><h2>উপকরণ ক্রয়</h2><p>এই এন্ট্রির মাধ্যমে Inventory-তে Stock In হবে।</p></div></div><form method="post" class="p5-form p5-form-two"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="purchase"><div class="p5-field"><label for="purchaseProject">প্রকল্প <b>*</b></label><select id="purchaseProject" name="project_id" data-p5-project-select required><option value="">প্রকল্প বাছুন</option><?php foreach($projects as $p): if($p['status']==='closed')continue; ?><option value="<?= (int)$p['id'] ?>"><?= e($p['title']) ?></option><?php endforeach; ?></select></div><div class="p5-field"><label for="purchaseSupplier">Supplier <b>*</b></label><select id="purchaseSupplier" name="supplier_id" required><option value="">Supplier বাছুন</option><?php foreach($allSuppliers as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['supplier_name']) ?></option><?php endforeach; ?></select></div><div class="p5-field p5-span2"><label for="purchaseItem">Material <b>*</b></label><select id="purchaseItem" name="item_id" data-p5-items required><option value="">Material বাছুন</option><?php foreach($items as $i): ?><option data-project="<?= (int)$i['project_id'] ?>" value="<?= (int)$i['id'] ?>"><?= e($i['item_name'].' · '.$i['project_title'].' ('.$i['unit'].')') ?></option><?php endforeach; ?></select></div><div class="p5-field"><label for="purchaseQty">Quantity <b>*</b></label><input id="purchaseQty" name="quantity" type="number" min="0.001" step="0.001" placeholder="যেমন: 200" required></div><div class="p5-field"><label for="purchaseUnitPrice">Unit Price (৳) <b>*</b></label><input id="purchaseUnitPrice" name="unit_price" type="number" min="0.01" step="0.01" placeholder="যেমন: 550" required></div><div class="p5-field"><label for="purchaseDate">ক্রয়ের তারিখ <b>*</b></label><input id="purchaseDate" name="purchase_date" type="date" value="<?= date('Y-m-d') ?>" required></div><div class="p5-field"><label for="invoiceNo">Invoice নম্বর <b>*</b></label><input id="invoiceNo" name="invoice_no" maxlength="100" placeholder="যেমন: INV-2026-001" required></div><div class="p5-field p5-span2"><label for="purchaseNotes">বিবরণ</label><input id="purchaseNotes" name="notes" maxlength="500" placeholder="যেমন: সাইট-এ সরবরাহ করা হয়েছে"></div><div class="p5-form-foot"><p>একবার Save করলে Purchase পরিবর্তন/মুছার সুবিধা নেই।</p><button type="submit" class="p5-btn p5-btn-primary">Purchase Save ↗</button></div></form></section></div>
<section class="p5-surface" id="new-payment"><div class="p5-section-heading"><div><span class="p5-overline">PAYABLES</span><h2>Supplier Payment</h2><p>Invoice-এর বকেয়া পর্যন্ত কিস্তিতে Payment রেকর্ড করুন।</p></div></div><form method="post" class="p5-form p5-form-three"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="payment_nonce" value="<?= e($_SESSION['p5_payment_nonce']) ?>"><div class="p5-field p5-span2"><label for="payPurchase">বকেয়া Purchase <b>*</b></label><select id="payPurchase" name="purchase_id" required><option value="">বকেয়া Invoice বাছুন</option><?php foreach($outstandingPurchases as $p):$due=round((float)$p['total_amount']-(float)$p['paid'],2);if($due<=0)continue; ?><option value="<?= (int)$p['id'] ?>">#<?= (int)$p['id'] ?> · <?= e($p['supplier_name']) ?> — বকেয়া <?= p5_cash_view($due) ?></option><?php endforeach; ?></select></div><div class="p5-field"><label for="payAmount">Payment Amount (৳) <b>*</b></label><input id="payAmount" type="number" step="0.01" min="0.01" name="amount" required placeholder="যেমন: 5000"></div><div class="p5-field"><label for="payDate">Payment Date <b>*</b></label><input id="payDate" type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></div><div class="p5-field"><label for="payMethod">Method <b>*</b></label><select id="payMethod" name="method"><option value="cash">Cash</option><option value="bank">Bank</option><option value="cheque">Cheque</option><option value="mobile">Mobile Banking</option></select></div><div class="p5-field"><label for="payReference">Reference</label><input id="payReference" name="reference_no" maxlength="120" placeholder="যেমন: CHQ-00012"></div><div class="p5-field p5-span2"><label for="payNote">মন্তব্য</label><input id="payNote" name="note" maxlength="500" placeholder="যেমন: প্রথম কিস্তি"></div><div class="p5-form-foot"><button class="p5-btn p5-btn-primary" type="submit">Payment Record করুন ↗</button></div></form></section>
<section class="p5-surface" id="purchase-directory"><div class="p5-section-heading"><div><span class="p5-overline">PURCHASE LEDGER</span><h2>ক্রয় ও বকেয়ার হিসাব</h2><p>সর্বশেষ ৩০০টি Invoice-এর অবস্থা</p></div><span class="p5-tag"><?= count($purchases) ?>টি</span></div><?php if($purchases): ?><div class="p5-toolbar"><label class="p5-search"><input type="search" data-p5-search placeholder="Supplier, Project, Invoice দিয়ে খুঁজুন..."></label></div><div class="p5-table-scroll"><table class="p5-table" data-p5-table><thead><tr><th>তারিখ/Invoice</th><th>Supplier</th><th>প্রকল্প / Material</th><th>পরিমাণ</th><th>Invoice Value</th><th>Paid</th><th>Due</th></tr></thead><tbody><?php foreach($purchases as $p): $due=max(0,round((float)$p['total_amount']-(float)$p['paid'],2)); ?><tr data-p5-row><td><strong>#<?= (int)$p['id'] ?></strong><small><?= e($p['purchase_date']) ?> · <?= e($p['invoice_no']??'—') ?></small></td><td><?= e($p['supplier_name']) ?></td><td><strong><?= e($p['project_title']) ?></strong><small><?= e($p['item_name']) ?></small></td><td><?= p5_qty_view($p['quantity']) ?> <?= e($p['unit']) ?></td><td><?= p5_cash_view($p['total_amount']) ?></td><td><?= p5_cash_view($p['paid']) ?></td><td><span class="p5-pill <?= $due>0?'warning':'success' ?>"><?= p5_cash_view($due) ?></span></td></tr><?php endforeach; ?></tbody></table></div><div data-p5-no-match class="p5-empty" hidden>কোনো মিল পাওয়া যায়নি।</div><?php else: ?><div class="p5-empty">এখনো Purchase Record তৈরি হয়নি।</div><?php endif; ?></section>
<section class="p5-surface" id="supplier-directory"><div class="p5-section-heading"><div><span class="p5-overline">SUPPLIER DIRECTORY</span><h2>সরবরাহকারীর তালিকা</h2></div></div><?php if($allSuppliers): ?><div class="p5-table-scroll"><table class="p5-table"><thead><tr><th>Supplier</th><th>Contact</th><th>Phone</th><th>Total Purchase</th><th>Outstanding</th></tr></thead><tbody><?php foreach($allSuppliers as $s): ?><tr><td><strong><?= e($s['supplier_name']) ?></strong></td><td><?= e($s['contact_name']??'—') ?></td><td><?= e($s['phone']??'—') ?></td><td><?= p5_cash_view($s['total']) ?></td><td><?= p5_cash_view((float)$s['total']-(float)$s['paid']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="p5-empty">কোনো Supplier নেই। উপরে নতুন Supplier যোগ করুন।</div><?php endif; ?></section>
<section class="p5-surface"><div class="p5-section-heading"><div><span class="p5-overline">PAYMENT HISTORY</span><h2>সাম্প্রতিক Payment</h2></div></div><?php if($payments): ?><div class="p5-table-scroll"><table class="p5-table"><thead><tr><th>তারিখ</th><th>Invoice</th><th>Supplier</th><th>Amount</th><th>Method</th><th>Reference</th></tr></thead><tbody><?php foreach($payments as $pay): ?><tr><td><?= e($pay['payment_date']) ?></td><td>#<?= (int)$pay['purchase_id'] ?></td><td><?= e($pay['supplier_name']) ?></td><td><?= p5_cash_view($pay['amount']) ?></td><td><?= e(ucfirst($pay['method'])) ?></td><td><?= e($pay['reference_no']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="p5-empty">এখনো Payment করা হয়নি।</div><?php endif; ?></section>
<p class="p5-note">Purchase Save করলে Stock In স্বয়ংক্রিয়ভাবে হয়। Purchase Invoice-কে আবার Daily Expense-এ যুক্ত করবেন না—Budget-এ খরচ দুইবার গণনা হবে। Payment-কে আবার খরচ হিসেবে গণনা করা হয়নি।</p></div>
